import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../../../core/errors/base_state.dart';
import '../../../../core/errors/failure.dart';
import '../../../../core/utils/formatters.dart';
import '../../../../shared/widgets/brand.dart';
import '../../domain/entities/sales_export.dart';
import '../controllers/sales_exports_controller.dart';
import '../widgets/sales_spreadsheet_dialog.dart';

/// Exportações: sales spreadsheets generated by period (day, week, month or a range),
/// kept to be downloaded again. Separate from Importações: these files are not batches.
class SalesExportsPage extends ConsumerStatefulWidget {
  const SalesExportsPage({super.key});

  @override
  ConsumerState<SalesExportsPage> createState() => _SalesExportsPageState();
}

class _SalesExportsPageState extends BaseState<SalesExportsPage>
    with SalesSpreadsheetDownload {
  Future<void> _download(SalesExport export) async {
    final saved = await runSafely(() => saveSalesExport(ref, export));
    if (saved == true && mounted) {
      ScaffoldMessenger.of(context)
        ..hideCurrentSnackBar()
        ..showSnackBar(const SnackBar(content: Text('Planilha salva.')));
    }
  }

  Future<void> _delete(SalesExport export) async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text('Excluir planilha gerada?'),
        content: Text(
          '"${export.fileName}" sai da lista de exportações. As vendas '
          'continuam no sistema; só o arquivo gerado é removido.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(context).pop(false),
            child: const Text('Cancelar'),
          ),
          FilledButton(
            onPressed: () => Navigator.of(context).pop(true),
            child: const Text('Excluir'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;

    await runSafely(
      () => ref.read(salesExportsControllerProvider.notifier).delete(export.id),
    );
  }

  @override
  Widget build(BuildContext context) {
    final exports = ref.watch(salesExportsControllerProvider);

    return Scaffold(
      floatingActionButton: FloatingActionButton.extended(
        heroTag: null,
        onPressed: isLoading
            ? null
            : () => downloadSalesSpreadsheet(DateTime.now()),
        icon: const Icon(Icons.table_view_outlined),
        label: const Text('Gerar planilha'),
      ),
      body: RefreshIndicator(
        onRefresh: () => ref.refresh(salesExportsControllerProvider.future),
        child: ListView(
          padding: const EdgeInsets.fromLTRB(16, 16, 16, 88),
          children: [
            Text(
              'Planilhas geradas',
              style: Theme.of(context).textTheme.titleMedium,
            ),
            const SizedBox(height: 4),
            Text(
              'Todas as vendas de um dia, uma semana, um mês ou um período: '
              'planilhas importadas, lançamentos manuais e caixa.',
              style: Theme.of(context).textTheme.bodySmall?.copyWith(
                color: Theme.of(context).colorScheme.onSurfaceVariant,
              ),
            ),
            const SizedBox(height: 12),
            ...switch (exports) {
              AsyncData(:final value) when value.isEmpty => [
                const EmptyState(
                  icon: Icons.table_view_outlined,
                  title: 'Nenhuma planilha gerada',
                  message:
                      'Toque em "Gerar planilha" ou, depois de lançar uma venda, '
                      'em "Gerar planilha" no aviso.',
                ),
              ],
              AsyncData(:final value) => [
                for (final export in value)
                  _ExportTile(
                    export: export,
                    onDownload: isLoading ? null : () => _download(export),
                    onDelete: isLoading ? null : () => _delete(export),
                  ),
              ],
              AsyncError(:final error) => [
                EmptyState(
                  icon: Icons.cloud_off_outlined,
                  title: 'Não foi possível carregar as planilhas',
                  message: error is Failure
                      ? error.generalMessages.join('\n')
                      : null,
                  action: FilledButton.tonal(
                    onPressed: () =>
                        ref.invalidate(salesExportsControllerProvider),
                    child: const Text('Tentar de novo'),
                  ),
                ),
              ],
              _ => [
                const Padding(
                  padding: EdgeInsets.all(32),
                  child: Center(child: CircularProgressIndicator()),
                ),
              ],
            },
          ],
        ),
      ),
    );
  }
}

class _ExportTile extends StatelessWidget {
  const _ExportTile({
    required this.export,
    required this.onDownload,
    required this.onDelete,
  });

  final SalesExport export;
  final VoidCallback? onDownload;
  final VoidCallback? onDelete;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final e = export;

    return Card(
      margin: const EdgeInsets.only(bottom: 8),
      clipBehavior: Clip.antiAlias,
      child: InkWell(
        onTap: onDownload,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(12, 12, 4, 12),
          child: Row(
            children: [
              TintedIcon(
                Icons.table_view_outlined,
                color: BrandColors.tintsOf(context)[3],
                size: 44,
              ),
              const SizedBox(width: 12),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      e.periodLabel,
                      style: theme.textTheme.titleSmall,
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                    ),
                    const SizedBox(height: 4),
                    Text.rich(
                      TextSpan(
                        children: [
                          TextSpan(
                            text: Formatters.currency(e.totalRevenue),
                            style: TextStyle(
                              color: theme.colorScheme.primary,
                              fontWeight: FontWeight.w600,
                            ),
                          ),
                          TextSpan(
                            text:
                                ' · ${Formatters.integer(e.salesCount)} '
                                '${e.salesCount == 1 ? 'venda' : 'vendas'}',
                          ),
                        ],
                      ),
                      style: theme.textTheme.bodyMedium,
                    ),
                    const SizedBox(height: 2),
                    Text(
                      'Gerada em ${Formatters.dateTime(e.createdAt)}'
                      '${e.createdBy.isEmpty ? '' : ' por ${e.createdBy}'}'
                      ' · ${e.fileName}',
                      style: theme.textTheme.bodySmall?.copyWith(
                        color: theme.colorScheme.onSurfaceVariant,
                      ),
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                    ),
                  ],
                ),
              ),
              IconButton(
                tooltip: 'Baixar',
                onPressed: onDownload,
                icon: const Icon(Icons.download_outlined),
              ),
              IconButton(
                tooltip: 'Excluir',
                onPressed: onDelete,
                icon: const Icon(Icons.delete_outline),
              ),
            ],
          ),
        ),
      ),
    );
  }
}
